{"event_id":"demo-benign-001","timestamp":"2026-10-29T10:00:00Z","source":"api-gateway","event_type":"request_succeeded","principal":"demo-user","resource":"orders-function","source_ip":"192.0.2.10","outcome":"success","invocations":1},
{"event_id":"demo-auth-001","timestamp":"2026-10-29T10:01:00Z","source":"cloudtrail","event_type":"authentication_failed","principal":"unknown-user","resource":"console-login","source_ip":"198.51.100.20","outcome":"denied"},
