HTML = '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">\n<title>SSMF Security Dashboard</title><style>\nbody{font-family:Segoe UI,Arial,sans-serif;background:#f4f7fb;color:#172033;margin:0}\nheader{background:#101b34;color:white;padding:24px 5vw}header h1{margin:0 0 6px;font-size:25px}\nmain{max-width:1200px;margin:24px auto;padding:0 18px}.muted{color:#6b7280}\n.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:14px;margin:18px 0}\n.card{background:white;border:1px solid #e2e8f0;border-radius:12px;padding:18px;box-shadow:0 3px 12px #1720330a}\n.num{font-size:30px;font-weight:700;margin-top:8px}.actions{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}\nbutton{border:0;border-radius:8px;background:#2457d6;color:white;padding:11px 15px;cursor:pointer;font-weight:600}\nbutton.secondary{background:#334155}table{width:100%;border-collapse:collapse;background:white;border-radius:10px;overflow:hidden}\nth,td{text-align:left;padding:12px;border-bottom:1px solid #e5eaf1;font-size:13px;vertical-align:top}\nth{background:#eaf0fa}.pill{padding:4px 8px;border-radius:20px;font-size:11px;font-weight:700;background:#e2e8f0}\n.critical{background:#fee2e2;color:#991b1b}.high{background:#ffedd5;color:#9a3412}.medium{background:#fef3c7;color:#92400e}\n.panel{background:white;border:1px solid #e2e8f0;border-radius:12px;padding:18px;margin:18px 0;overflow:auto}\n#message{min-height:20px;color:#2457d6}footer{padding:20px;color:#64748b;font-size:12px}\n</style></head><body><header><h1>Serverless Security Monitoring Framework</h1>\n<div>Centralized event normalization, rule-based detection and risk triage</div></header><main>\n<p class="muted">Local prototype · Synthetic demo data · Not connected to a live AWS account</p>\n<div class="actions"><button onclick="loadDemo()">Load demo events</button><button class="secondary" onclick="refresh()">Refresh dashboard</button></div><div id="message"></div>\n<section class="cards"><div class="card">Events processed<div class="num" id="total">0</div></div>\n<div class="card">Events with alerts<div class="num" id="alerts">0</div></div>\n<div class="card">Critical alerts<div class="num" id="critical">0</div></div>\n<div class="card">High alerts<div class="num" id="high">0</div></div></section>\n<div class="panel"><h2>Ingest a test event</h2><p class="muted">Use JSON to test a normal or suspicious event.</p>\n<textarea id="eventInput" rows="4" style="width:100%;box-sizing:border-box;padding:10px;border:1px solid #cbd5e1;border-radius:8px">{"event_type":"authentication_failed","principal":"test-user","resource":"login-function","source_ip":"198.51.100.10","outcome":"denied"}</textarea>\n<div class="actions"><button onclick="submitEvent()">Process event</button></div></div>\n<div class="panel"><h2>Recent events and findings</h2><table><thead><tr><th>Time</th><th>Type / Resource</th><th>Principal / Source IP</th><th>Risk</th><th>Findings</th></tr></thead><tbody id="rows"></tbody></table></div>\n</main><footer>Educational prototype. Detection is rule-based and limited to implemented rules. Do not use as a production security control.</footer>\n<script>\nasync function refresh(){let [s,e]=await Promise.all([fetch(\'/api/summary\').then(r=>r.json()),fetch(\'/api/events\').then(r=>r.json())]);\nfor(let k of [\'total_events\',\'alerts\',\'critical_alerts\',\'high_alerts\'])document.getElementById(({total_events:\'total\',alerts:\'alerts\',critical_alerts:\'critical\',high_alerts:\'high\'})[k]).textContent=s[k];\ndocument.getElementById(\'rows\').innerHTML=e.map(x=>{let fs=x.findings.length?x.findings.map(f=>`${esc(f.title)} (${esc(f.severity)})`).join(\'<br>\'):\'No finding\';\nlet sev=x.max_risk_score>=95?\'critical\':x.max_risk_score>=80?\'high\':x.max_risk_score>=50?\'medium\':\'\';\nreturn `<tr><td>${esc(x.timestamp)}</td><td><b>${esc(x.event_type)}</b><br>${esc(x.resource)}</td><td>${esc(x.principal)}<br>${esc(x.source_ip)}</td><td><span class="pill ${sev}">${x.max_risk_score}</span></td><td>${fs}</td></tr>`}).join(\'\');}\nfunction esc(s){return String(s??\'\').replace(/[&<>"\']/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c]));}\nasync function loadDemo(){let r=await fetch(\'/api/demo\',{method:\'POST\'});let j=await r.json();document.getElementById(\'message\').textContent=`Processed ${j.processed} synthetic events.`;refresh();}\nasync function submitEvent(){try{let e=JSON.parse(document.getElementById(\'eventInput\').value);let r=await fetch(\'/api/ingest\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:JSON.stringify(e)});let j=await r.json();document.getElementById(\'message\').textContent=j.alert?`Alert generated: ${j.findings.map(f=>f.title).join(\', \')}`:\'Event processed; no rule matched.\';refresh();}catch(e){document.getElementById(\'message\').textContent=\'Invalid JSON: \'+e.message;}}\nrefresh();\n</script></body></html>'
class Handler(BaseHTTPRequestHandler):
    def send_data(self,code,body,content_type="application/json"):
        payload=body if isinstance(body,bytes) else (body.encode() if isinstance(body,str) else json.dumps(body).encode())
        self.send_response(code); self.send_header("Content-Type",content_type); self.send_header("Content-Length",str(len(payload))); self.end_headers(); self.wfile.write(payload)
    def do_GET(self):
        if self.path=="/": return self.send_data(200,HTML,"text/html; charset=utf-8")
        if self.path=="/api/summary": return self.send_data(200,store.summary())
        if self.path=="/api/events": return self.send_data(200,store.list_events(100))
        return self.send_data(404,{"error":"not found"})
    def do_POST(self):
        length=int(self.headers.get("Content-Length","0"))
        try: payload=json.loads(self.rfile.read(length) or b"{}")
        except json.JSONDecodeError: return self.send_data(400,{"error":"invalid JSON"})
        if self.path=="/api/ingest": return self.send_data(200,process_event(payload,store))
        if self.path=="/api/demo":
            for event in DEMO_EVENTS: process_event(event,store)
            return self.send_data(200,{"processed":len(DEMO_EVENTS)})
        return self.send_data(404,{"error":"not found"})
    def log_message(self,fmt,*args): print("[http]",fmt%args)
if __name__=="__main__":
    print("SSMF dashboard running at http://127.0.0.1:8000")
    ThreadingHTTPServer(("127.0.0.1",8000),Handler).serve_forever()
